export type BackupView = { 
/**
 * File name; what `restore_backup` takes.
 */
name: string, 
/**
 * Local time it was taken: `YYYY-MM-DD HH:MM:SS`.
 */
created: string, 
/**
 * Size of the file.
 */
bytes: number, 
/**
 * Taken automatically before a rename or delete of several files (or before a page was replaced).
 */
before: boolean, 
/**
 * The second folder holds a copy (always false without a second folder).
 */
in_mirror: boolean, };
export type PageVersionView = { 
/**
 * What `page_version_text` and `restore_page_version` take.
 */
id: string, 
/**
 * Unix time in milliseconds when it was recorded.
 */
at_ms: number, 
/**
 * Size of the file.
 */
bytes: number, };
export type PageVersionArgs = { 
/**
 * Page name.
 */
page: string, 
/**
 * `PageVersionView.id`, or `current` (`page_version_text` only) for the file as it is now.
 */
id: string, };
export type BackupList = { 
/**
 * The folder in use (the setting, or the default).
 */
dir: string, 
/**
 * The default folder.
 */
default_dir: string, 
/**
 * Snapshots, newest first.
 */
backups: Array<BackupView>, 
/**
 * The last automatic snapshot failed with this message (cleared by the next success).
 */
error: string | null, 
/**
 * The second folder as set (empty = none).
 */
mirror_dir: string, 
/**
 * Copying to the second folder failed with this message (a disk that is not plugged in, ...).
 */
mirror_error: string | null, };
export type RestoreBackupArgs = { 
/**
 * `BackupView.name`.
 */
name: string, 
/**
 * Folder to create or fill; must be empty and outside the graph folder.
 */
target: string, };
export type RestoreBackupPageArgs = { 
/**
 * `BackupView.name`.
 */
name: string, 
/**
 * Page name.
 */
page: string, };
export type BackupNameArgs = { 
/**
 * `BackupView.name`.
 */
name: string, };
export type DiffLine = { 
/**
 * `add` (in the snapshot, not now), `del` (now, not in the snapshot), `same` (context) or `gap` (unchanged lines
 * left out; the text is empty).
 */
kind: string, 
/**
 * The line.
 */
text: string, };
export type DeviceRestorePreview = { 
/**
 * The snapshot holds device settings (older ones do not).
 */
available: boolean, 
/**
 * Nothing differs.
 */
same: boolean, 
/**
 * The changed lines, in file order.
 */
lines: Array<DiffLine>, };
export type BackupChange = { 
/**
 * Path in the graph folder, or `.notatnik-device/<name>` for a device file.
 */
path: string, 
/**
 * `changed`, `only_snapshot` (restoring would bring it back) or `only_now` (created since the snapshot).
 */
status: string, 
/**
 * Not text: no lines are compared.
 */
binary: boolean, 
/**
 * Lines only in the snapshot.
 */
added: number, 
/**
 * Lines only now.
 */
removed: number, };
export type BackupCompare = { 
/**
 * Sorted by path; empty when nothing differs.
 */
changes: Array<BackupChange>, };
export type BackupFileArgs = { 
/**
 * `BackupView.name`.
 */
name: string, 
/**
 * `BackupChange.path`.
 */
path: string, };
export type BackupFileDiff = { 
/**
 * Not text.
 */
binary: boolean, 
/**
 * Too long and too different to compare.
 */
too_large: boolean, 
/**
 * The lines.
 */
lines: Array<DiffLine>, };

